mapper.select:
		with TMP as (
		    select
		        bbt.BOOKSET_ID
		    from
		        BOK_BATCH_TASK_TODO bbt inner join BOK_BOOKSET bbs on bbt.BOOKSET_ID = bbs.BOOKSET_ID
		    where
		        1 = 1

	        	and bbt.SEQ_NO = #{seqNo,jdbcType=VARCHAR}

	        	and bbt.BOOKSET_DATE = #{bookSetDate,jdbcType=DATE}
	        	and bbt.BOOK_DATE = #{bookDate,jdbcType=DATE}
	        	and bbt.HAPPEN_DATE = #{happenDate,jdbcType=DATE}

	        	and bbt.TASK_ID = #{taskId,jdbcType=VARCHAR}


	        	and bbt.IS_SUB_BOOKSET = #{isSubBookSet,jdbcType=VARCHAR}

		)
		SELECT
		    tpd.TRADE_DATE tradeDate,
		    ftp.IRS_TYPE as ps,
		    frin.BENCHMARK_ID benchMarkId,
		    tpd.PRIN_AMT as tradeAmt,
		    ftp.VDATE vDate,
		    ftp.MDATE mDate,
		    ftp.TERM_TYPE termType,
		    fccr.YIELD * 100 as yield,
		    fcpr.FIRST_PAY_DATE as firstvDate,
		    nvl(ext.TRADE_DATE, to_date('2099-12-31', 'yyyy-mm-dd')) as endDate,
		    nvl(ext.SETTLE_DATE, to_date('2099-12-31', 'yyyy-mm-dd')) as sureEndDate,
		    decode(ext.TRADE_DATE , to_date('2099-12-31', 'yyyy-mm-dd') , 'N' , 'Y') as isOverTime,
		    ftp.CALENDAR_ID calendarId,
		    ftp.CCY ccy,
		    ftp.FINPROD_ID finprodId
		FROM
		    tmp
		    INNER JOIN bok_deal_accounting  bda ON tmp.bookset_id = bda.bookset_id
		    INNER JOIN trd_product_deal tpd ON bda.busi_no = tpd.trade_id
		    INNER JOIN fin_trade_product ftp ON ftp.finprod_id = tpd.trade_id
		    LEFT JOIN fin_rate_info frin ON frin.finprod_id = ftp.finprod_id
		                            AND frin.branch = #{branch}
		                            AND frin.int_type = #{intType02}
		                           	AND frin.eff_date = ftp.vdate
		    LEFT JOIN fin_rate_info frin_r ON frin_r.finprod_id = ftp.finprod_id
		                            AND frin_r.branch = #{branch}
		                            AND frin_r.int_type = #{intType01}
		                            AND frin_r.eff_date = ftp.vdate
		    LEFT JOIN fin_cash_calc_rule fccr ON frin_r.cash_id = fccr.cash_id
		                                 AND fccr.is_initial = #{isInitial}
		    LEFT JOIN fin_cash_pay_rule fcpr ON fcpr.cash_id = fccr.cash_id
		                                        AND fcpr.eff_date = tpd.vdate
		    LEFT JOIN trd_product_deal ext ON ext.finprod_id = ftp.finprod_id
	                                     	 AND ext.ps IN (
		                                            #{C5},
		                                            #{C20}
		                                        )
                                      		AND ext.trade_status = #{tradeStatus}
   		where
   			1=1
       		and tpd.VDATE  <=  #{happenDate, jdbcType=DATE}
      		and tpd.MDATE  >=  #{happenDate, jdbcType=DATE}
        	and tpd.FINPROD_TYPE = #{finProdType, jdbcType=VARCHAR}
        	and tpd.TRADE_STATUS = #{tradeStatus, jdbcType=VARCHAR}
        	and tpd.PS = #{PS, jdbcType=VARCHAR}

select
	DECODE(SUBSTR(myci.KEY_POINT,1,1),'.','0'||myci.KEY_POINT,myci.KEY_POINT) as code,
	myci.YIELD as rate
from
	MST_YIELD_CURVE_INFO myci
	inner join MST_CURVE_DEF mcd on mcd.CURVE_CODE = myci.CURVE_CODE
where
	mcd.BASE_INT_CODE = #{baseIntCode}
	and mcd.CURVE_INT_TYPE = #{curveIntType02}
	and mcd.PRICE_TYPE = #{priceType} 
	and myci.CURVE_DATE = #{happenDate, jdbcType=DATE}

select
	to_char(CDATE, 'yyyy-MM-dd')
from
	MST_HOLIDAY
where
	CALENDAR_ID = #{calendarId}
	and CDATE  >=  #{happenDate01,jdbcType=DATE}
	and CDATE  <=  #{happenDate02,jdbcType=DATE}
	and IS_HOLIDAY = #{isHoliday}
